package frc.robot.subsystems;
import com.ctre.phoenix6.StatusSignal;
import com.ctre.phoenix6.hardware.TalonFX;
import au.grapplerobotics.LaserCan;
import edu.wpi.first.units.measure.Angle;
import edu.wpi.first.wpilibj.DigitalInput;
import edu.wpi.first.wpilibj2.command.Command;
import edu.wpi.first.wpilibj2.command.Commands;
import edu.wpi.first.wpilibj2.command.SubsystemBase;
import edu.wpi.first.wpilibj.smartdashboard.SmartDashboard;
public class ElevatorSubsystem extends SubsystemBase {
	private final TalonFX elevatorMotor;
	private final LaserCan laserCan;
	private final DigitalInput bottomLimit;
	private final StatusSignal<Angle> elevatorPosition;
	private static final double SCORE_HEIGHT = 50.0;
	private static final double POSITION_TOLERANCE = 2.0;

	public ElevatorSubsystem() {
		elevatorMotor = new TalonFX(5);
		elevatorPosition = elevatorMotor.getPosition();
		laserCan = new LaserCan(0);
		bottomLimit = new DigitalInput(1);
	}

	public Command zeroElevator() {
		return run(() -> {
			elevatorMotor.set(-0.2);
		})
		.until(() -> bottomLimit.get())
		.finallyDo(() -> {
			elevatorMotor.stopMotor();
			elevatorMotor.setPosition(0);
		});
	}

	public boolean hasGamePiece() {
		LaserCan.Measurement measurement = laserCan.getMeasurement();
		if (measurement == null) {
			return false;
		}
		return measurement.distance_mm < 75;
	}

	public Command moveToScoreHeight() {
		return run(() -> {
			elevatorPosition.refresh();
			double current = elevatorPosition.getValueAsDouble();
			if (current < SCORE_HEIGHT) {
				elevatorMotor.set(0.4);
			} else {
				elevatorMotor.set(-0.2);
			}
		})
		.until(() -> {
			double current = elevatorPosition.getValueAsDouble();
			return Math.abs(current - SCORE_HEIGHT) < POSITION_TOLERANCE;
		})
		.finallyDo(() -> {
			elevatorMotor.stopMotor();
		});
	}

	public Command prepareToScore() {
		return Commands.either(
			moveToScoreHeight(),
			Commands.none(),
			this::hasGamePiece
		);
	}

	public void moveElevator(double speed) {
		if (speed < 0 && bottomLimit.get()) {
			elevatorMotor.stopMotor();
			return;
		}
		elevatorMotor.set(speed);
	}

	@Override
	public void periodic() {
		elevatorPosition.refresh();
		SmartDashboard.putNumber("Elevator Position", elevatorPosition.getValueAsDouble());
	}
}

