from phoenix6.hardware import TalonFX
from phoenix6 import StatusSignal
from lasercan import LaserCan
from wpilib import DigitalInput
from commands2 import SubsystemBase
from commands2.cmd import either, none

class ElevatorSubsystem(SubsystemBase):
	SCORE_HEIGHT = 50.0
	POSITION_TOLERANCE = 2.0

	def __init__(self):
		super().__init__()
		self.elevator_motor = TalonFX(5)
		self.laser_can = LaserCan(0)
		self.bottom_limit = DigitalInput(1)
		self.elevator_position = self.elevator_motor.get_position()

	def zero_elevator(self):
		return self.run(lambda: self.elevator_motor.set(-0.2)) \
			.until(lambda: self.bottom_limit.get()) \
			.finallyDo(lambda: (self.elevator_motor.stop_motor(), self.elevator_motor.set_position(0)))

	def has_game_piece(self):
		measurement = self.laser_can.get_measurement()
		if measurement is None:
			return False
		return measurement.distance_mm < 75

	def move_to_score_height(self):
		def drive():
			self.elevator_position.refresh()
			current = self.elevator_position.value_as_double

			if current < self.SCORE_HEIGHT:
				self.elevator_motor.set(0.4)
			else:
				self.elevator_motor.set(-0.2)

		def at_target():
			current = self.elevator_position.value_as_double
			return abs(current - self.SCORE_HEIGHT) < self.POSITION_TOLERANCE

		return self.run(drive) \
			.until(at_target) \
			.finallyDo(lambda: self.elevator_motor.stop_motor())

	def prepare_to_score(self):
		return either(
			self.move_to_score_height(),
			none(),
			self.has_game_piece
		)

	def move_elevator(self, speed: float):
		if speed < 0 and self.bottom_limit.get():
			self.elevator_motor.stop_motor()
			return
		self.elevator_motor.set(speed)

	def periodic(self):
		self.elevator_position.refresh()
		 SmartDashboard.putNumber(
			"Elevator Position",
			 self.elevator_position.value_as_double
		)

