class ElevatorSubsystem : public frc2::SubsystemBase {
public:
	ElevatorSubsystem()
		: elevatorMotor(5),
		  laserCan(0),
		  bottomLimit(1),
		  elevatorPosition(elevatorMotor.GetPosition()) {}

	frc2::CommandPtr ZeroElevator() {
		return Run([this] {
			elevatorMotor.Set(-0.2);
		})
		.Until([this] {
			return bottomLimit.Get();
		})
		.FinallyDo([this] {
			elevatorMotor.StopMotor();
			elevatorMotor.SetPosition(0_tr);
		});
	}

	bool HasGamePiece() {
		auto measurement = laserCan.GetMeasurement();
		if (!measurement) {
			return false;
		}
		return measurement->distance_mm < 75;
	}

	frc2::CommandPtr MoveToScoreHeight() {
		return Run([this] {
			elevatorPosition.Refresh();
			double current = elevatorPosition.GetValueAsDouble();

			if (current < kScoreHeight) {
				elevatorMotor.Set(0.4);
			} else {
				elevatorMotor.Set(-0.2);
			}
		})
		.Until([this] {
			double current = elevatorPosition.GetValueAsDouble();
			return std::abs(current - kScoreHeight) < kPositionTolerance;
		})
		.FinallyDo([this] {
			elevatorMotor.StopMotor();
		});
	}

	frc2::CommandPtr PrepareToScore() {
		return frc2::cmd::Either(
			MoveToScoreHeight(),
			frc2::cmd::None(),
			[this] { return HasGamePiece(); }
		);
	}

	void MoveElevator(double speed) {
		if (speed < 0 && bottomLimit.Get()) {
			elevatorMotor.StopMotor();
			return;
		}
		elevatorMotor.Set(speed);
	}

	void Periodic() override {
		elevatorPosition.Refresh();
		frc::SmartDashboard::PutNumber(
			"Elevator Position",
			elevatorPosition.GetValueAsDouble()
		);
	}

private:
	ctre::phoenix6::hardware::TalonFX elevatorMotor;
	LaserCan laserCan;
	frc::DigitalInput bottomLimit;
	ctre::phoenix6::StatusSignal<units::angle::turn_t> elevatorPosition;

	static constexpr double kScoreHeight = 50.0;
	static constexpr double kPositionTolerance = 2.0;
};
